  "validation.page.scss": ".patterns {\n  display: grid;\n  gap: 16px;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr));\n  align-items: start;\n}\n\n.async mat-slider {\n  display: block;\n  width: calc(100% - 16px);\n  margin-inline: 8px;\n}\n\n.ok {\n  color: var(--app-ok);\n}\n\n.status {\n  margin: 0;\n  min-height: 1.4em;\n  font: var(--mat-sys-label-large);\n}\n\n.actions {\n  margin-top: 16px;\n}\n",
  "validation.page.ts": "import { Component, computed, inject, signal } from '@angular/core';\nimport { FormField, form } from '@angular/forms/signals';\nimport { MatButtonModule } from '@angular/material/button';\nimport { MatCheckboxModule } from '@angular/material/checkbox';\nimport { MatFormFieldModule } from '@angular/material/form-field';\nimport { MatIconModule } from '@angular/material/icon';\nimport { MatInputModule } from '@angular/material/input';\nimport { MatProgressSpinnerModule } from '@angular/material/progress-spinner';\nimport { MatSliderModule } from '@angular/material/slider';\nimport { RequestLogStore } from '../../core/fake-backend/request-log.store';\nimport { DemoPage } from '../../shared/demo-page/demo-page';\nimport { MetricTile } from '../../shared/metric-tile/metric-tile';\nimport { EMPTY_SIGN_UP, RESERVED_WORDS, SignUp, signUpSchema } from './validation.rules';\nimport { BEFORE_AFTER, SNIPPETS } from './validation.snippets';\n\n/** Video 002 – Validation patterns: built-ins, when, cross-field, custom rules, validateHttp. */\n@Component({\n  selector: 'app-validation-page',\n  imports: [\n    DemoPage,\n    FormField,\n    MatButtonModule,\n    MatCheckboxModule,\n    MatFormFieldModule,\n    MatIconModule,\n    MatInputModule,\n    MatProgressSpinnerModule,\n    MatSliderModule,\n    MetricTile,\n  ],\n  templateUrl: './validation.page.html',\n  styleUrl: './validation.page.scss',\n})\nexport class ValidationPage {\n  readonly #log = inject(RequestLogStore);\n  readonly snippets = SNIPPETS;\n  readonly beforeAfter = BEFORE_AFTER;\n  readonly reserved = RESERVED_WORDS.join(', ');\n\n  readonly debounceMs = signal(400);\n  readonly model = signal<SignUp>({ ...EMPTY_SIGN_UP });\n  readonly signUp = form(this.model, signUpSchema(this.debounceMs));\n\n  readonly #usernameChecks = computed(() =>\n    this.#log.entries().filter((e) => e.url.includes('/api/usernames/')),\n  );\n  readonly requestsSent = computed(() => this.#usernameChecks().length);\n  readonly requestsCancelled = computed(\n    () => this.#usernameChecks().filter((e) => e.cancelled).length,\n  );\n  readonly keystrokes = signal(0);\n\n  readonly handleStatus = computed(() => {\n    const handle = this.signUp.handle();\n    if (handle.pending()) return 'Checking…';\n    if (handle.invalid()) return handle.errors()[0]?.message ?? 'Invalid';\n    return handle.value() ? 'Available' : '';\n  });\n\n  onHandleInput(): void {\n    this.keystrokes.update((n) => n + 1);\n  }\n\n  validateAll(): void {\n    this.signUp().markAsTouched();\n  }\n\n  reset(): void {\n    this.model.set({ ...EMPTY_SIGN_UP });\n    this.signUp().reset();\n    this.keystrokes.set(0);\n  }\n}\n",
  "validation.rules.ts": "import { HttpContext } from '@angular/common/http';\nimport { Signal } from '@angular/core';\nimport {\n  ValidationError,\n  email,\n  max,\n  min,\n  minLength,\n  pattern,\n  required,\n  schema,\n  validate,\n  validateHttp,\n} from '@angular/forms/signals';\nimport { SKIP_ERROR_HANDLING } from '../../core/http/http-context';\n\nexport interface SignUp {\n  username: string;\n  email: string;\n  age: number | null;\n  isCompany: boolean;\n  companyName: string;\n  password: string;\n  confirmPassword: string;\n  nickname: string;\n  handle: string;\n}\n\nexport const EMPTY_SIGN_UP: SignUp = {\n  username: '',\n  email: '',\n  age: null,\n  isCompany: false,\n  companyName: '',\n  password: '',\n  confirmPassword: '',\n  nickname: '',\n  handle: '',\n};\n\nexport const RESERVED_WORDS = ['admin', 'test', 'root', 'null'];\n\n/** 4. A custom rule is a plain function: return `{ kind, message }` or null. */\nexport function noReservedWords(value: string): ValidationError | null {\n  const hit = RESERVED_WORDS.find((word) => value.toLowerCase().includes(word));\n  return hit ? { kind: 'reserved', message: `\"${hit}\" is a reserved word.` } : null;\n}\n\nexport interface Availability {\n  available: boolean;\n}\n\n/** Waits `ms` – used as a dynamic debounce so the demo slider can change it at runtime. */\nexport function wait(ms: number): Promise<void> {\n  return new Promise((resolve) => setTimeout(resolve, ms));\n}\n\n/** All five validation patterns in one schema. `debounceMs` is a signal so the UI can tune it. */\nexport function signUpSchema(debounceMs: Signal<number>) {\n  return schema<SignUp>((path) => {\n    // 1. Built-in validators\n    required(path.username, { message: 'Username is required.' });\n    minLength(path.username, 3, { message: 'At least 3 characters.' });\n    pattern(path.username, /^[a-z0-9_]+$/, { message: 'Lowercase letters, digits and _ only.' });\n    required(path.email, { message: 'Email is required.' });\n    email(path.email, { message: 'Please enter a valid email.' });\n    min(path.age, 18, { message: 'Minimum age is 18.' });\n    max(path.age, 120, { message: 'Maximum age is 120.' });\n\n    // 2. Conditional: only required when the checkbox is ticked\n    required(path.companyName, {\n      when: ({ valueOf }) => valueOf(path.isCompany),\n      message: 'Company name is required for company accounts.',\n    });\n\n    // 3. Cross-field: compare with another field via valueOf()\n    minLength(path.password, 8, { message: 'At least 8 characters.' });\n    validate(path.confirmPassword, ({ value, valueOf }) =>\n      value() !== valueOf(path.password)\n        ? { kind: 'mismatch', message: 'Passwords do not match.' }\n        : null,\n    );\n\n    // 4. Custom rule function\n    validate(path.nickname, ({ value }) => noReservedWords(value()));\n\n    // 5. Async: HTTP check with built-in debounce. Runs only once the sync rules pass.\n    required(path.handle, { message: 'Pick a handle.' });\n    minLength(path.handle, 3, { message: 'At least 3 characters.' });\n    validateHttp(path.handle, {\n      request: ({ value }) => ({\n        url: `/api/usernames/${encodeURIComponent(value())}/available`,\n        context: new HttpContext().set(SKIP_ERROR_HANDLING, true),\n      }),\n      debounce: () => wait(debounceMs()), // static alternative: `debounce: 300`\n      onSuccess: (result: Availability) =>\n        result.available ? null : { kind: 'taken', message: 'This handle is already taken.' },\n      onError: () => ({ kind: 'unreachable', message: 'Could not check availability.' }),\n    });\n  });\n}\n",
